<template>
  <nav class="nav-wrap">
    <div class="nav-shell">
      <RouterLink class="brand" to="/" @click="closeMenu">
        <span class="brand-pill">TERENCE</span>
      </RouterLink>

      <div class="desktop-nav">
        <RouterLink
          v-for="item in navItems"
          :key="item.id"
          :to="item.to"
          class="nav-link"
          :class="{ active: isActive(item.to) }"
        >
          <component :is="item.icon" :size="16" />
          <span>{{ item.label }}</span>
        </RouterLink>
      </div>

      <RouterLink class="contact-link" to="/contact" @click="closeMenu">
        联系我
      </RouterLink>

      <button
        class="menu-toggle"
        type="button"
        :aria-expanded="isMenuOpen ? 'true' : 'false'"
        aria-label="切换导航菜单"
        @click="toggleMenu"
      >
        <component :is="isMenuOpen ? X : Menu" :size="22" />
      </button>
    </div>

    <div v-if="isMenuOpen" class="mobile-panel">
      <RouterLink
        v-for="item in navItems"
        :key="`${item.id}-mobile`"
        :to="item.to"
        class="mobile-link"
        :class="{ active: isActive(item.to) }"
        @click="closeMenu"
      >
        <component :is="item.icon" :size="18" />
        <span>{{ item.label }}</span>
      </RouterLink>

      <RouterLink class="mobile-contact" to="/contact" @click="closeMenu">
        联系我
      </RouterLink>
    </div>
  </nav>
</template>

<script>
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { Bike, Briefcase, Cat, GlassWater, Home, Menu, X } from 'lucide-vue-next'

export default {
  name: 'NavBar',
  setup() {
    const route = useRoute()
    const isMenuOpen = ref(false)

    const navItems = computed(() => [
      { id: 'home', label: '首页', icon: Home, to: '/' },
      { id: 'projects', label: '项目', icon: Briefcase, to: '/projects' },
      { id: 'cats', label: '猫咪', icon: Cat, to: '/cats' },
      { id: 'cocktails', label: '鸡尾酒', icon: GlassWater, to: '/cocktails' },
      { id: 'motorcycles', label: '摩托车', icon: Bike, to: '/motorcycles' }
    ])

    const closeMenu = () => {
      isMenuOpen.value = false
    }

    const toggleMenu = () => {
      isMenuOpen.value = !isMenuOpen.value
    }

    const isActive = (path) => route.path === path

    watch(
      () => route.path,
      () => {
        closeMenu()
      }
    )

    return {
      Bike,
      Menu,
      X,
      closeMenu,
      isActive,
      isMenuOpen,
      navItems,
      toggleMenu
    }
  }
}
</script>

