<script>
import { ref, onMounted, onUnmounted, nextTick } from "vue";
import gsap from "gsap";
import HighlightTag from "@/components/common/HighlightTag.vue";
import TegakiRendererCore from "@/components/tegaki/TegakiRendererCore.vue";
import bundle from "tegaki/fonts/caveat";

/** LCP 头像：与 public/index.html 里 preload 的 href 同一路径 */
const heroAvatarUrl = `${process.env.BASE_URL}media/hero-avatar.webp`;

/** 每个浏览器标签页会话内只播一次开屏（关闭标签后下次会再播） */
const HOME_INTRO_STORAGE_KEY = "terence-portfolio-home-intro-v1";

const readHomeIntroSeen = () => {
  if (typeof window === "undefined") return false;
  try {
    return window.sessionStorage.getItem(HOME_INTRO_STORAGE_KEY) === "1";
  } catch (_) {
    return false;
  }
};

const writeHomeIntroSeen = () => {
  if (typeof window === "undefined") return;
  try {
    window.sessionStorage.setItem(HOME_INTRO_STORAGE_KEY, "1");
  } catch (_) {
    /* ignore quota / private mode */
  }
};

/** 开屏层 pointer-events:none 时滚轮仍会滚动下层文档，导致结束后视口不在顶部 */
let introScrollLocked = false;

const lockIntroScroll = () => {
  if (typeof document === "undefined") return;
  if (introScrollLocked) return;
  introScrollLocked = true;
  document.documentElement.style.overflow = "hidden";
  document.body.style.overflow = "hidden";
};

const unlockIntroScroll = () => {
  if (!introScrollLocked) return;
  introScrollLocked = false;
  if (typeof document === "undefined") return;
  document.documentElement.style.removeProperty("overflow");
  document.body.style.removeProperty("overflow");
};

export default {
  name: "HomeHero",
  emits: ["go-projects"],
  components: { HighlightTag, TegakiRenderer: TegakiRendererCore },
  setup() {
    const homeIntroAlreadySeen = readHomeIntroSeen();

    const nameTagRef = ref(null);
    const introLayerRef = ref(null);
    const introBackdropRef = ref(null);
    const introFlyRef = ref(null);
    const introFlyClusterRef = ref(null);
    const introProgressWrapRef = ref(null);
    const introProgressFillRef = ref(null);
    const introNameRootRef = ref(null);
    const introNameBgRef = ref(null);
    const introTegakiRef = ref(null);
    const introDone = ref(homeIntroAlreadySeen);
    const introHeadline = "Terence Portfolio";
    const introHandwritingFont = bundle;

    let introTween;
    let progressTween;
    let introTegakiVerifyTimer = 0;
    let introFlyStarted = false;
    let introUnmounted = false;

    const INTRO_ANIM_DURATION_SEC = 1.2;
    const INTRO_HANDWRITING_DURATION_SEC = 2.6;
    const INTRO_PROGRESS_PAD_AFTER_TEXT_SEC = 0.25;
    const introHandwritingTime = {
      mode: "uncontrolled",
      duration: INTRO_HANDWRITING_DURATION_SEC,
      delay: 0.12,
      playing: true,
    };
    const shouldForceIntroTextFallback = () => {
      if (typeof navigator === "undefined") return false;
      const ua = navigator.userAgent || "";
      const isiOSUA = /iPhone|iPad|iPod/i.test(ua);
      const isTouchMac =
        navigator.platform === "MacIntel" && Number(navigator.maxTouchPoints || 0) > 1;
      const isAppleMobile = isiOSUA || isTouchMac;
      const isWebKitEngine = /AppleWebKit/i.test(ua) && !/CriOS|FxiOS|EdgiOS/i.test(ua);
      const isIOSChrome = /CriOS/i.test(ua);
      return isAppleMobile && (isWebKitEngine || isIOSChrome);
    };
    const getIntroProgressDurationSec = () =>
      INTRO_HANDWRITING_DURATION_SEC + INTRO_PROGRESS_PAD_AFTER_TEXT_SEC;

    const introTegakiFallback = ref(
      typeof navigator !== "undefined" && shouldForceIntroTextFallback()
    );

    const enableIntroTextFallback = () => {
      introTegakiFallback.value = true;
    };

    const scheduleIntroTegakiHealthCheck = () => {
      if (typeof window === "undefined") return;
      window.clearTimeout(introTegakiVerifyTimer);
      introTegakiVerifyTimer = window.setTimeout(() => {
        if (introUnmounted) return;
        const el = introTegakiRef.value;
        if (!el) return;
        const hasCanvas = !!el.querySelector("canvas[data-tegaki='canvas']");
        const width = el.getBoundingClientRect().width;
        if (!hasCanvas || width < 2) enableIntroTextFallback();
      }, 380);
    };

    const mountIntroTegaki = () => {
      if (introUnmounted) return;
      if (introTegakiFallback.value) return;
      scheduleIntroTegakiHealthCheck();
    };

    const stopProgressTween = () => {
      progressTween?.kill();
      progressTween = undefined;
      const fill = introProgressFillRef.value;
      if (fill) gsap.set(fill, { scaleX: 1, transformOrigin: "left center" });
    };

    const startProgressTween = () => {
      if (introUnmounted) return;
      const fill = introProgressFillRef.value;
      if (!fill) return;
      gsap.set(fill, { scaleX: 0, transformOrigin: "left center" });
      const progressDur = getIntroProgressDurationSec();
      progressTween = gsap.to(fill, {
        scaleX: 1,
        duration: progressDur,
        ease: "none",
        onComplete: () => {
          progressTween = undefined;
          if (!introUnmounted) runIntro();
        },
      });
    };

    const applyIntroNameFinalState = () => {
      const root = introNameRootRef.value;
      const bg = introNameBgRef.value;
      if (root) root.classList.add("hero-intro__name--solid");
      if (bg) gsap.set(bg, { opacity: 1 });
    };

    const playIntroNameReveal = () => {
      if (introUnmounted) return;
      if (typeof window === "undefined") {
        startProgressTween();
        return;
      }
      if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
        applyIntroNameFinalState();
        runIntro();
        return;
      }

      const bg = introNameBgRef.value;
      const root = introNameRootRef.value;
      if (root) root.classList.remove("hero-intro__name--solid");
      if (bg) gsap.set(bg, { opacity: 0 });
      startProgressTween();
    };

    const finishIntro = () => {
      if (introUnmounted) return;
      writeHomeIntroSeen();
      stopProgressTween();
      introTween = undefined;

      const clearIntroGsap = () => {
        const els = [
          introFlyRef.value,
          introNameBgRef.value,
          introBackdropRef.value,
          introProgressWrapRef.value,
          introProgressFillRef.value,
        ].filter(Boolean);
        els.forEach((el) => {
          gsap.killTweensOf(el);
          gsap.set(el, { clearProps: "transform,opacity" });
        });
      };

      nextTick(() => {
        if (introUnmounted) return;
        clearIntroGsap();
        nextTick(() => {
          if (introUnmounted) return;
          introDone.value = true;
          unlockIntroScroll();
        });
      });
    };

    const runIntro = () => {
      if (introUnmounted) return;
      if (introFlyStarted) return;
      if (typeof window === "undefined") {
        finishIntro();
        return;
      }
      if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
        finishIntro();
        return;
      }

      const flyer = introFlyRef.value;
      if (!flyer) {
        finishIntro();
        return;
      }

      introFlyStarted = true;

      const backdrop = introBackdropRef.value;
      const moveDur = INTRO_ANIM_DURATION_SEC;
      const nameBg = introNameBgRef.value;
      const nameRoot = introNameRootRef.value;

      introTween = gsap.timeline({
        onComplete: () => {
          if (!introUnmounted) finishIntro();
        },
      });

      if (nameBg) {
        gsap.set(nameBg, { opacity: 0 });
        introTween.to(
          nameBg,
          {
            opacity: 1,
            duration: moveDur,
            ease: "power1.inOut",
          },
          0
        );
      }

      if (nameRoot) {
        nameRoot.classList.remove("hero-intro__name--solid");
        introTween.call(
          () => {
            introNameRootRef.value?.classList.add("hero-intro__name--solid");
          },
          null,
          moveDur * 0.42
        );
      }

      const progressWrap = introProgressWrapRef.value;
      if (progressWrap) {
        introTween.to(
          progressWrap,
          {
            opacity: 0,
            duration: 0.22,
            ease: "power2.out",
          },
          0
        );
      }

      const bgFadeEase = "power2.inOut";

      if (backdrop) {
        introTween.to(
          backdrop,
          {
            opacity: 0,
            duration: moveDur,
            ease: bgFadeEase,
          },
          0
        );
      }

      introTween.to(
        flyer,
        {
          opacity: 0,
          duration: Math.min(0.24, moveDur),
          ease: "power2.out",
        },
        0
      );
    };

    onMounted(async () => {
      if (homeIntroAlreadySeen) return;
      if (typeof window !== "undefined") window.scrollTo({ top: 0, left: 0, behavior: "auto" });
      lockIntroScroll();
      await nextTick();
      mountIntroTegaki();
      requestAnimationFrame(() => {
        if (introUnmounted) return;
        if (typeof window === "undefined") {
          runIntro();
          return;
        }
        if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
          applyIntroNameFinalState();
          runIntro();
          return;
        }
        playIntroNameReveal();
      });
    });

    onUnmounted(() => {
      introUnmounted = true;
      if (typeof window !== "undefined") window.clearTimeout(introTegakiVerifyTimer);
      unlockIntroScroll();
      stopProgressTween();
      introTween?.kill();
      if (introFlyRef.value) gsap.killTweensOf(introFlyRef.value);
      if (introFlyClusterRef.value)
        gsap.killTweensOf(introFlyClusterRef.value);
      if (introBackdropRef.value) gsap.killTweensOf(introBackdropRef.value);
      if (introProgressWrapRef.value)
        gsap.killTweensOf(introProgressWrapRef.value);
    });

    return {
      heroAvatarUrl,
      nameTagRef,
      introLayerRef,
      introBackdropRef,
      introFlyRef,
      introFlyClusterRef,
      introProgressWrapRef,
      introProgressFillRef,
      introNameRootRef,
      introNameBgRef,
      introTegakiRef,
      introHeadline,
      introHandwritingFont,
      introHandwritingTime,
      introTegakiFallback,
      introDone,
    };
  },
};
</script>

