}

.scroll-to-top:focus-visible {
  outline: 3px solid var(--text-accent);
  outline-offset: 3px;
}

.back-top-fade-enter-active,
.back-top-fade-leave-active {
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.back-top-fade-enter-from,
