<template>
  <section ref="sectionRef" class="ssh-easter-egg section">
    <!-- 模块标题 -->
    <header class="ssh-header">
      <h2>
        <HighlightTag
          bg-color="#FFC107"
          text-color="#111827"
          rotate="1.5deg"
          padding="4px 14px"
          font-weight="900"
        >
          SSH 连接
        </HighlightTag>
      </h2>
      <p class="subtitle">
        在终端上藏的一个小彩蛋
      </p>
    </header>

    <div
      ref="terminalRef"
      class="neo-frame neo-frame-dark terminal-container"
    >
      <!-- 终端头部 -->
      <div class="terminal-header">
        <div class="header-dots">
          <span class="dot red"></span>
          <span class="dot yellow"></span>
          <span class="dot green"></span>
        </div>
        <div class="header-title">Terminal</div>
        <div class="header-actions">
          <TerminalIcon :size="18" />
        </div>
      </div>

      <!-- 终端内容 -->
      <div class="terminal-body" @click="copySSH">
        <div class="prompt-line">
          <span class="prompt-user">guest@terenzzzz.cn</span>
          <span class="prompt-sep">:</span>
          <span class="prompt-dir">~</span>
          <span class="prompt-char">$</span>
          <span class="command-text">ssh -p 592 ssh.terenzzzz.cn</span>
        </div>
        
        <div class="output-area">
          <p class="typing-text">Connecting to ssh.terenzzzz.cn...</p>
        </div>

        <!-- 复制区域：原生 button 改善移动端可点中与聚焦 -->
        <button
          type="button"
          class="copy-box"
          :class="{ 'is-copied': copied }"
          @click.stop="copySSH"
        >
          <code class="ssh-code">{{ sshCommand }}</code>
          <span class="copy-button">
            <CopyIcon v-if="!copied" :size="18" />
            <CheckIcon v-else :size="18" />
            <span>{{ copied ? '已复制' : '复制' }}</span>
          </span>
        </button>
      </div>

      <!-- 装饰元素 -->
      <div class="terminal-footer">
        <div class="status-item">
          <div class="pulse-dot"></div>
          <span>Server Online</span>
        </div>
        <div class="status-item">
          <span>UTF-8</span>
        </div>
      </div>
    </div>
  </section>
</template>

<script>
import { ref, onMounted, onUnmounted, nextTick } from 'vue'
import gsap from 'gsap'
import { ScrollTrigger } from 'gsap/ScrollTrigger'
import HighlightTag from '@/components/common/HighlightTag.vue'
import {
  Terminal as TerminalIcon,
  Copy as CopyIcon,
  Check as CheckIcon,
} from 'lucide-vue-next'

gsap.registerPlugin(ScrollTrigger)

const TERMINAL_TILT_DEG = 22
/**
 * 用负 margin 把终端抬上去压住标题（不依赖 scrub 是否为 0，首屏就可见）；
 * 滚动结束时 translateY 同为该值，与 margin 抵消，落到正常排版位置。
 */
const TERMINAL_OVERLAP_PX = 68

/** iOS / iPadOS：clipboard 的 Promise 常脱离用户手势，需在同步阶段走 legacy */
const isIOSLike = () =>
  typeof navigator !== 'undefined' &&
  (/iPad|iPhone|iPod/.test(navigator.userAgent) ||
    (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1))

/** 真机触摸：优先同步 execCommand，避免异步 clipboard 在手势外失败 */
const isCoarsePointer = () =>
  typeof window !== 'undefined' &&
  typeof window.matchMedia === 'function' &&
  window.matchMedia('(pointer: coarse)').matches

function legacyCopyText(text) {
  const ta = document.createElement('textarea')
  ta.value = text
  ta.setAttribute('readonly', '')
  ta.style.position = 'fixed'
  ta.style.left = '0'
  ta.style.top = '0'
  ta.style.width = '1px'
  ta.style.height = '1px'
  ta.style.padding = '0'
  ta.style.border = 'none'
  ta.style.outline = 'none'
  ta.style.boxShadow = 'none'
  ta.style.background = 'transparent'
  ta.style.opacity = '0'
  ta.style.fontSize = '16px'
  document.body.appendChild(ta)
  ta.focus()
  ta.select()
  ta.setSelectionRange(0, text.length)
  let ok = false
  try {
    ok = document.execCommand('copy')
  } catch (_) {
    ok = false
  }
  document.body.removeChild(ta)
  return ok
}

export default {
  name: 'SSHEasterEgg',
  components: {
    HighlightTag,
    TerminalIcon,
    CopyIcon,
    CheckIcon,
  },
  setup() {
    const sshCommand = 'ssh -p 592 ssh.terenzzzz.cn'
    const copied = ref(false)
    const terminalRef = ref(null)
    const sectionRef = ref(null)
    let gsapCtx
    let lastCopyAt = 0

    const markCopied = () => {
      copied.value = true
      setTimeout(() => {
        copied.value = false
      }, 2000)
    }

    const copySSH = () => {
      const now = typeof performance !== 'undefined' ? performance.now() : Date.now()
      if (now - lastCopyAt < 450) return
      lastCopyAt = now

      const text = sshCommand

      if (isIOSLike() || isCoarsePointer()) {
        if (legacyCopyText(text)) {
          markCopied()
          return
        }
      }

      if (
        navigator.clipboard?.writeText &&
        typeof window !== 'undefined' &&
        window.isSecureContext
      ) {
        navigator.clipboard.writeText(text).then(markCopied).catch(() => {
          if (legacyCopyText(text)) markCopied()
        })
        return
      }

      if (legacyCopyText(text)) markCopied()
    }

    onMounted(() => {
      nextTick(() => {
        const el = terminalRef.value
        if (!el) return

        const reduceMotion =
          typeof window !== 'undefined' &&
          window.matchMedia('(prefers-reduced-motion: reduce)').matches

        if (reduceMotion) {
          gsap.set(el, { clearProps: 'transform' })
          el.classList.add('terminal-container--reduce-motion')
          return
        }

        const section = sectionRef.value
        if (!section) return

        gsapCtx = gsap.context(() => {
          gsap.fromTo(
            el,
            {
              rotateX: TERMINAL_TILT_DEG,
              y: 0,
              transformOrigin: '50% 55%',
              force3D: true,
            },
            {
              rotateX: 0,
              y: TERMINAL_OVERLAP_PX,
              ease: 'none',
              scrollTrigger: {
                trigger: section,
                start: 'top 88%',
                end: 'top 34%',
                scrub: 0.38,
                invalidateOnRefresh: true,
              },
            }
          )
          requestAnimationFrame(() => ScrollTrigger.refresh())
        }, section)
      })
    })

    onUnmounted(() => {
      gsapCtx?.revert()
      gsapCtx = undefined
    })

    return {
      sshCommand,
      copied,
      copySSH,
      terminalRef,
      sectionRef,
    }
  },
}
</script>

