<template>
  <section class="section contact-page">
    <RevealOnView>
      <header class="head">
        <h1>让我们 <HighlightTag bg-color="#4D61FC" text-color="#fff">聊聊</HighlightTag> 吧</h1>
        <p>无论是新项目、合作机会，还是想打个招呼，都欢迎联系我。</p>
      </header>
    </RevealOnView>

    <div class="contact-grid">
      <RevealOnView>
        <article class="card status neo-frame">
          <h3>目前的动态</h3>
          <p>我目前正在寻找有趣的设计开发合作机会。如果你有想法，欢迎随时联系我。</p>
        </article>
      </RevealOnView>
      <RevealOnView :delay="70">
        <article class="card form neo-frame">
          <h3>发送消息</h3>
          <form class="form" @submit.prevent="sendEmail">
            <input v-model.trim="formData.name" type="text" placeholder="您的姓名" required />
            <input v-model.trim="formData.email" type="email" placeholder="您的邮箱" required />
            <input v-model.trim="formData.title" type="text" placeholder="主题" required />
            <textarea v-model.trim="formData.message" rows="4" placeholder="您的消息" required></textarea>
            <NeoButton variant="dark" type="submit" :disabled="isSending">
              {{ isSending ? '发送中...' : '发送消息' }}
            </NeoButton>
            <p v-if="showSuccess" class="status-message success">消息发送成功，我会尽快回复你。</p>
            <p v-if="showWarning" class="status-message error">发送失败，请稍后重试。</p>
          </form>
        </article>
      </RevealOnView>
      <RevealOnView :delay="140">
        <article class="card info neo-frame">
          <h3>联系方式</h3>
          <div class="item">
            <small>邮箱</small>
            <strong>terence592592@gmail.com</strong>
          </div>
          <div class="item">
            <small>微信</small>
            <strong>@Terenz_</strong>
          </div>
          <div class="item">
            <small>Instagram</small>
            <strong>@terenzzzz_</strong>
          </div>
          <div class="item">
            <small>GitHub</small>
            <strong>@terenzzzz</strong>
          </div>
        </article>
      </RevealOnView>
    </div>
  </section>
</template>

<script>
import emailjs from '@emailjs/browser'
import HighlightTag from '@/components/common/HighlightTag.vue'
import NeoButton from '@/components/common/NeoButton.vue'

export default {
  name: 'ContactView',
  components: { HighlightTag, NeoButton },
  data() {
    return {
      formData: {
        name: '',
        email: '',
        title: '',
        message: ''
      },
      showSuccess: false,
      showWarning: false,
      isSending: false
    }
  },
  mounted() {
    emailjs.init('Bbu94PNlJ6zyFtwL6')
  },
  methods: {
    sendEmail() {
      if (this.isSending) return
      this.isSending = true

      const serviceID = 'service_so9udlr'
      const templateID = 'template_v1ijpqg'
      const templateParams = {
        name: this.formData.name,
        email: this.formData.email,
        title: this.formData.title,
        message: this.formData.message
      }

      emailjs.send(serviceID, templateID, templateParams).then(
        () => {
          this.isSending = false
          this.showSuccess = true
          this.showWarning = false
          this.formData = {
            name: '',
            email: '',
            title: '',
            message: ''
          }
        },
        () => {
          this.isSending = false
          this.showWarning = true
          this.showSuccess = false
        }
      )
    }
  }
}
</script>

