<template>
  <section v-if="featuredProjects.length" class="featured-wrap">
    <div class="section featured-inner">
      <header class="featured-header">
        <h2>
          <HighlightTag
            bg-color="#FF5C8D"
            text-color="#ffffff"
            rotate="-2.5deg"
            padding="4px 14px"
            font-weight="900"
          >
            近作
          </HighlightTag>
        </h2>
        <p class="subtitle">
          最近做的一些 Web 向的东西，有vibe coding的, 也有手搓的
        </p>
      </header>

      <div
        ref="carouselHost"
        class="carousel-outer"
        :class="{ 'is-in-view': carouselInView }"
      >
        <Swiper
          class="featured-swiper"
          :modules="swiperModules"
          :navigation="featuredProjects.length > 1"
          :pagination="{ clickable: true }"
          :loop="featuredProjects.length > 2"
          :slides-per-view="1.08"
          :space-between="18"
          :speed="480"
          :watch-overflow="true"
          :observer="true"
          :observe-parents="true"
          :breakpoints="swiperBreakpoints"
        >
          <SwiperSlide
            v-for="(project, index) in featuredProjects"
            :key="project.slug"
            class="featured-slide"
          >
            <RouterLink
              class="slide-link"
              :to="{ name: 'project-detail', params: { slug: project.slug } }"
            >
              <article
                class="slide-card neo-frame neo-frame-panel"
                :style="{ '--slide-i': index }"
              >
                <div class="slide-head">
                  <div
                    class="icon-box"
                    :style="{ background: iconTint(project.color) }"
                  >
                    <img
                      class="icon-img"
                      :src="project.icon"
                      alt=""
                      width="40"
                      height="40"
                      loading="lazy"
                      decoding="async"
                    />
                  </div>
                  <div class="slide-copy">
                    <h3>{{ project.title }}</h3>
                    <p class="excerpt">{{ project.description }}</p>
                  </div>
                </div>
              </article>
            </RouterLink>
          </SwiperSlide>
        </Swiper>
      </div>

      <div class="cta-row">
        <RouterLink class="cta-all neo-press" to="/projects">
          查看更多项目
        </RouterLink>
      </div>
    </div>
  </section>
</template>

<script>
import HighlightTag from '@/components/common/HighlightTag.vue'
import { Swiper, SwiperSlide } from 'swiper/vue'
import { Navigation, Pagination } from 'swiper/modules'
import 'swiper/css'
import 'swiper/css/navigation'
import 'swiper/css/pagination'

import { FEATURED_PROJECT_SLUGS } from '@/data/siteData'
import { PROJECTS } from '@/data/projects'

export default {
  name: 'FeaturedProjectsCarousel',
  components: {
    HighlightTag,
    Swiper,
    SwiperSlide
  },
  data() {
    return {
      carouselInView: false,
      carouselObserver: null,
      swiperModules: [Navigation, Pagination],
      swiperBreakpoints: {
        480: { slidesPerView: 1.15, spaceBetween: 20 },
        768: { slidesPerView: 2, spaceBetween: 22 },
        1024: { slidesPerView: 2.35, spaceBetween: 24 },
        1200: { slidesPerView: 3, spaceBetween: 24 }
      }
    }
  },
  mounted() {
    this.initCarouselReveal()
  },
  beforeUnmount() {
    this.carouselObserver?.disconnect()
    this.carouselObserver = null
  },
  computed: {
    featuredProjects() {
      return FEATURED_PROJECT_SLUGS.map((slug) =>
        PROJECTS.find((p) => p.slug === slug)
      ).filter(Boolean)
    }
  },
  methods: {
    initCarouselReveal() {
      if (typeof window === 'undefined') return
      if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
        this.carouselInView = true
        return
      }
      this.$nextTick(() => {
        const el = this.$refs.carouselHost
        if (!el) {
          this.carouselInView = true
          return
        }
        const tryShow = () => {
          const rect = el.getBoundingClientRect()
          const h = window.innerHeight
          if (rect.width > 0 && rect.top < h && rect.bottom > 0) {
            this.carouselInView = true
            this.carouselObserver?.disconnect()
            this.carouselObserver = null
            return true
          }
          return false
        }
        if (tryShow()) return
        this.carouselObserver = new IntersectionObserver(
          (entries) => {
            for (const e of entries) {
              if (e.isIntersecting) {
                this.carouselInView = true
                this.carouselObserver?.disconnect()
                this.carouselObserver = null
                break
              }
            }
          },
          { root: null, rootMargin: '0px 0px -8% 0px', threshold: 0.06 }
        )
        this.carouselObserver.observe(el)
        requestAnimationFrame(() => {
          if (!this.carouselInView) tryShow()
        })
      })
    },
    iconTint(hex) {
      if (!hex || typeof hex !== 'string') return '#dbeafe'
      const c = hex.replace('#', '')
      if (c.length !== 6) return '#dbeafe'
      return `#${c}33`
    }
  }
}
</script>

