<script>
import HighlightTag from '@/components/common/HighlightTag.vue'
import { Swiper, SwiperSlide } from 'swiper/vue'
import { Navigation, Pagination } from 'swiper/modules'
import 'swiper/css'
import 'swiper/css/navigation'
import 'swiper/css/pagination'
import earbudsSilhouette from '@/assets/earbuds-silhouette.webp'
import esportsSilhouette from '@/assets/esports-silhouette.webp'
import makerSilhouette from '@/assets/maker-silhouette.webp'
import homeLifeSilhouette from '@/assets/home-life-silhouette.webp'
import officeSilhouette from '@/assets/office-silhouette.webp'
import heatedVestSilhouette from '@/assets/heated-vest-silhouette.webp'
import commsSilhouette from '@/assets/comms-silhouette.webp'
import smartApplianceSilhouette from '@/assets/smart-appliance-silhouette.webp'

export default {
  name: 'ShopifyBrandCarousel',
  components: {
    HighlightTag,
    Swiper,
    SwiperSlide
  },
  data() {
    return {
      carouselInView: false,
      carouselObserver: null,
      swiperModules: [Navigation, Pagination],
      swiperBreakpoints: {
        480: { slidesPerView: 1.15, spaceBetween: 20 },
        768: { slidesPerView: 2, spaceBetween: 22 },
        1024: { slidesPerView: 2.35, spaceBetween: 24 },
        1200: { slidesPerView: 3, spaceBetween: 24 }
      },
      brandSlides: [
        {
          category: '运动耳机',
          description: '面向跑步、骑行、训练等户外运动场景，强调佩戴稳定性、环境感知与长时间使用体验。',
          accent: '#F5EFEA',
          soft: '#F5EFEA',
          visual: 'earbuds'
        },
        {
          category: '电竞外设',
          description: '覆盖键盘、鼠标、耳机等游戏装备，注重性能参数、操控反馈和电竞风格的视觉表达。',
          accent: '#4D61FC',
          soft: '#4D61FC',
          visual: 'esports'
        },
        {
          category: '创客硬件',
          description: '围绕 3D 打印、CNC、开发板与工具配件，面向创客、工程师和教育实验场景。',
          accent: '#FFC107',
          soft: '#FFC107',
          visual: 'maker'
        },
        {
          category: '家庭生活',
          description: '覆盖厨房小家电、饮食器具与日常生活用品，强调质感设计和更轻松的居家体验。',
          accent: '#FF5C8D',
          soft: '#FF5C8D',
          visual: 'home-life'
        },
        {
          category: '智能电器',
          description: '面向家用空气、温控与清洁等智能设备场景，突出节能、舒适和自动化生活方式。',
          accent: '#4D61FC',
          soft: '#4D61FC',
          visual: 'smart'
        },
        {
          category: '电子通信',
          description: '涵盖对讲机、无线通信设备与配件，强调户外作业、团队协作和可靠连接能力。',
          accent: '#FFC107',
          soft: '#FFC107',
          visual: 'comms'
        },
        {
          category: '办公设备',
          description: '覆盖标签打印、移动办公和桌面效率设备，服务中小企业、仓储和日常办公场景。',
          accent: '#FF5C8D',
          soft: '#FF5C8D',
          visual: 'office'
        },
        {
          category: '功能服装',
          description: '以加热服装和户外保暖装备为主，面向通勤、露营、滑雪和寒冷环境下的穿着需求。',
          accent: '#FF6B00',
          soft: '#FFB703',
          visual: 'heated-vest'
        }
      ]
    }
  },
  mounted() {
    this.initCarouselReveal()
  },
  beforeUnmount() {
    this.carouselObserver?.disconnect()
    this.carouselObserver = null
  },
  methods: {
    stageStyle(brand) {
      return {
        '--accent': brand.accent,
        '--soft': brand.soft,
        '--earbuds-art': `url(${earbudsSilhouette})`,
        '--esports-art': `url(${esportsSilhouette})`,
        '--maker-art': `url(${makerSilhouette})`,
        '--home-life-art': `url(${homeLifeSilhouette})`,
        '--smart-art': `url(${smartApplianceSilhouette})`,
        '--office-art': `url(${officeSilhouette})`,
        '--heated-vest-art': `url(${heatedVestSilhouette})`,
        '--comms-art': `url(${commsSilhouette})`
      }
    },
    initCarouselReveal() {
      if (typeof window === 'undefined') return
      if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
        this.carouselInView = true
        return
      }
      this.$nextTick(() => {
        const el = this.$refs.carouselHost
        if (!el) {
          this.carouselInView = true
          return
        }
        const tryShow = () => {
          const rect = el.getBoundingClientRect()
          const h = window.innerHeight
          if (rect.width > 0 && rect.top < h && rect.bottom > 0) {
            this.carouselInView = true
            this.carouselObserver?.disconnect()
            this.carouselObserver = null
            return true
          }
          return false
        }
        if (tryShow()) return
        this.carouselObserver = new IntersectionObserver(
          (entries) => {
            for (const e of entries) {
              if (e.isIntersecting) {
                this.carouselInView = true
                this.carouselObserver?.disconnect()
                this.carouselObserver = null
                break
              }
            }
          },
          { root: null, rootMargin: '0px 0px -8% 0px', threshold: 0.06 }
        )
        this.carouselObserver.observe(el)
        requestAnimationFrame(() => {
          if (!this.carouselInView) tryShow()
        })
      })
    }
  }
}
</script>

