<script>
export default { inheritAttrs: false };
</script>

<script setup>
/* global defineProps, defineExpose */
import { computed, onMounted, onUnmounted, ref, watch } from "vue";
import { TegakiEngine } from "tegaki/core";

const props = defineProps({
  text: { type: String, default: undefined },
  font: { type: [Object, String], default: undefined },
  time: { type: [Object, Number, String], default: undefined },
  effects: { type: Object, default: undefined },
  timing: { type: Object, default: undefined },
  quality: { type: String, default: undefined },
  showOverlay: { type: Boolean, default: undefined },
  onComplete: { type: Function, default: undefined },
  direction: { type: String, default: undefined },
});

const container = ref(null);
let engine = null;

const engineOptions = computed(() => ({
  text: props.text,
  font: props.font,
  time: props.time,
  effects: props.effects,
  quality: props.quality,
  timing: props.timing,
  showOverlay: props.showOverlay,
  direction: props.direction,
  onComplete: props.onComplete,
}));

function escapeAttr(s) {
  return s.replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function escapeHtml(s) {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function htmlCreateElement(tag, nodeProps, ...children) {
  const parts = [];
  for (const [key, value] of Object.entries(nodeProps)) {
    if (value == null || value === false) continue;
    if (key === "style" && typeof value === "object") {
      const css = Object.entries(value)
        .filter(([, v]) => v != null)
        .map(([k, v]) => {
          const prop = k.startsWith("--") ? k : k.replace(/[A-Z]/g, (m) => `-${m.toLowerCase()}`);
          const val = typeof v === "number" && !k.startsWith("--") ? `${v}px` : String(v);
          return `${prop}:${val}`;
        })
        .join(";");
      if (css) parts.push(`style="${escapeAttr(css)}"`);
    } else if (typeof value === "boolean") {
      parts.push(key);
    } else {
      parts.push(`${key}="${escapeAttr(String(value))}"`);
    }
  }
  const open = parts.length > 0 ? `<${tag} ${parts.join(" ")}>` : `<${tag}>`;
  const content = children
    .map((c) => (typeof c === "string" && !c.startsWith("<") ? escapeHtml(c) : c))
    .join("");
  return `${open}${content}</${tag}>`;
}

const { rootProps, content: innerHtml } = TegakiEngine.renderElements(
  engineOptions.value,
  htmlCreateElement
);

onMounted(() => {
  if (!container.value) return;
  engine = new TegakiEngine(container.value, { ...engineOptions.value, adopt: true });
});

onUnmounted(() => {
  engine?.destroy();
  engine = null;
});

watch(
  engineOptions,
  (options) => {
    engine?.update(options);
  },
  { deep: true }
);

defineExpose({ engine, element: container });
</script>

<template>
  <div
    ref="container"
    data-tegaki="root"
    :style="rootProps.style"
    v-bind="$attrs"
    v-html="innerHtml"
  />
</template>
