<template>
  <div
    ref="root"
    class="reveal-on-view"
    :class="{ 'is-visible': visible }"
    :style="revealStyle"
  >
    <slot />
  </div>
</template>

<script>
export default {
  name: 'RevealOnView',
  props: {
    /** 进入视口后的过渡延迟（毫秒），用于同级模块错峰 */
    delay: {
      type: Number,
      default: 0
    },
    rootMargin: {
      type: String,
      default: '0px 0px -10% 0px'
    },
    threshold: {
      type: Number,
      default: 0.06
    },
    once: {
      type: Boolean,
      default: true
    }
  },
  data() {
    return {
      visible: false,
      observer: null,
      resizeObserver: null
    }
  },
  computed: {
    revealStyle() {
      return { '--reveal-delay': `${this.delay}ms` }
    }
  },
  mounted() {
    this.initObserver()
  },
  beforeUnmount() {
    this.disposeObserver()
  },
  methods: {
    disposeObserver() {
      this.observer?.disconnect()
      this.observer = null
      this.resizeObserver?.disconnect()
      this.resizeObserver = null
    },
    /**
     * 首帧 / ResizeObserver：按「完整浏览器视口」判断，只要真在屏上就显示，
     * 避免与 IO 同一套严格规则导致首屏模块（如大 Hero 下方的块）误判为不可见。
     * 滚动进入视口仍仅由下方 IntersectionObserver（rootMargin + threshold）控制。
     */
    intersectsFullViewport(el) {
      const rect = el.getBoundingClientRect()
      const h = window.innerHeight
      const w = window.innerWidth
      if (rect.width <= 0 || rect.height <= 0) return false
      if (rect.right <= 0 || rect.left >= w) return false
      if (rect.bottom <= 0 || rect.top >= h) return false
      const visTop = Math.max(0, rect.top)
      const visBottom = Math.min(h, rect.bottom)
      return visBottom - visTop > 0
    },
    applyInitialVisibilityIfNeeded() {
      if (this.visible) return
      const el = this.$refs.root
      if (!el) return
      if (this.intersectsFullViewport(el)) {
        this.visible = true
        this.resizeObserver?.disconnect()
        this.resizeObserver = null
        if (this.once) this.disposeObserver()
      }
    },
    scheduleInitialCheck() {
      this.$nextTick(() => {
        requestAnimationFrame(() => {
          this.applyInitialVisibilityIfNeeded()
          requestAnimationFrame(() => this.applyInitialVisibilityIfNeeded())
        })
      })
    },
    initObserver() {
      if (typeof window === 'undefined') return

      if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
        this.visible = true
        return
      }

      const el = this.$refs.root
      if (!el) return

      this.observer = new IntersectionObserver(
        (entries) => {
          for (const e of entries) {
            if (e.isIntersecting) {
              this.visible = true
              if (this.once) this.disposeObserver()
            }
          }
        },
        {
          root: null,
          rootMargin: this.rootMargin,
          threshold: this.threshold
        }
      )

      this.observer.observe(el)

      if (typeof ResizeObserver !== 'undefined') {
        this.resizeObserver = new ResizeObserver(() => {
          if (this.visible) {
            this.resizeObserver?.disconnect()
            this.resizeObserver = null
            return
          }
          this.applyInitialVisibilityIfNeeded()
        })
        this.resizeObserver.observe(el)
      }

      this.scheduleInitialCheck()
    }
  }
}
</script>

<style scoped>
.reveal-on-view {
  width: 100%;
  min-width: 0;
  opacity: 0;
  transform: translate3d(0, 22px, 0);
  transition:
    opacity 0.78s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.78s cubic-bezier(0.22, 1, 0.36, 1);
  transition-delay: var(--reveal-delay, 0ms);
}

.reveal-on-view.is-visible {
  opacity: 1;
  transform: translate3d(0, 0, 0);
}

@media (prefers-reduced-motion: reduce) {
  .reveal-on-view {
    opacity: 1;
    transform: none;
    transition: none;
  }
}
</style>
