import projectsMeta from './projects-meta.json'

export const PROJECT_ASSET_FOLDER_MAP = {
  aftershot: 'aftershot',
  forkandpour: 'forkAndPour',
  musicbuddy: 'musicBuddy',
  healthyexpert: 'healthyExpert',
  birdwatching: 'birdWatching',
  trafistats: 'trafiStats',
  ewaste: 'ewaste',
  alcocalc: 'alcoCalc',
  jofind: 'joFind',
  netify: 'netify',
  whattomix: 'whatToMix',
  thebigwalk: 'theBigWalk',
  meowid: 'meowID',
  shopifytemplateinspector: 'shopifyTemplateInspector',
  shopifyschemavisualbuilder: 'shopifySchemaVisualBuilder',
  web2figma: 'web2figma',
  responsivecomparer: 'responsiveComparer'
}

const PROJECT_IMAGE_CONTEXT = require.context('../assets/project', true, /\.(png|jpe?g|webp|svg)$/)
const IMAGE_EXTENSIONS = ['webp', 'png', 'jpg', 'jpeg', 'svg']

function resolveProjectAsset(slug, baseName) {
  const folder = PROJECT_ASSET_FOLDER_MAP[slug]
  if (!folder) return ''

  const keys = PROJECT_IMAGE_CONTEXT.keys()
  for (const ext of IMAGE_EXTENSIONS) {
    const targetKey = `./${folder}/${baseName}.${ext}`
    if (keys.includes(targetKey)) {
      const mod = PROJECT_IMAGE_CONTEXT(targetKey)
      return mod?.default || mod || ''
    }
  }
  return ''
}

export const PROJECTS = projectsMeta.map((item) => {
  const image = resolveProjectAsset(item.slug, 'cover') || item.image
  const icon = resolveProjectAsset(item.slug, 'icon') || image
  return {
    ...item,
    image,
    icon
  }
})

export const getProjectBySlug = (slug) => PROJECTS.find((item) => item.slug === slug)
