<template>
  <section class="section projects-page">
    <RevealOnView>
      <div class="head">
        <div class="kicker">
          <span class="line"></span>
          <span class="label">Portfolio</span>
        </div>
        <h1>项目 <HighlightTag bg-color="#f472b6">精选</HighlightTag></h1>
        <p>从 Web、移动端到工具型产品，下面是我在界面、数据与工程实现上做过的一些完整案例与迭代记录。</p>
      </div>
    </RevealOnView>

    <RevealOnView
      v-for="(section, idx) in projectSections"
      :key="section.category"
      class="project-category-reveal"
      :class="{ 'project-category-reveal--first': idx === 0 }"
      :delay="idx * 48"
    >
      <section
        class="project-section"
        :aria-labelledby="`projects-cat-${idx}`"
      >
        <h2 :id="`projects-cat-${idx}`" class="section-title">{{ section.category }}</h2>
        <div class="grid">
          <ProjectCard
            v-for="project in section.projects"
            :key="project.slug"
            :project="project"
            @open="openProject(project.slug)"
          />
        </div>
      </section>
    </RevealOnView>
  </section>
</template>

<script>
import HighlightTag from '@/components/common/HighlightTag.vue'
import ProjectCard from '@/components/projects/ProjectCard.vue'
import { PROJECTS } from '@/data/projects'

const SECTION_ORDER = ['工具型产品', '网页应用', '移动应用', '独立站']

function sectionKeyFromCategory(category) {
  const cat = category || '其他'
  if (cat === '安卓应用' || cat === 'iOS应用') return '移动应用'
  return cat
}

export default {
  name: 'ProjectsView',
  components: { HighlightTag, ProjectCard },
  computed: {
    projectSections() {
      const bySection = new Map()
      for (const p of PROJECTS) {
        const key = sectionKeyFromCategory(p.category)
        if (!bySection.has(key)) bySection.set(key, [])
        bySection.get(key).push(p)
      }

      const ordered = []
      for (const title of SECTION_ORDER) {
        const list = bySection.get(title)
        if (list?.length) {
          ordered.push({ category: title, projects: list })
          bySection.delete(title)
        }
      }

      const rest = [...bySection.entries()].sort(([a], [b]) => a.localeCompare(b, 'zh-CN'))
      for (const [category, projects] of rest) {
        if (projects.length) ordered.push({ category, projects })
      }

      return ordered
    }
  },
  methods: {
    openProject(slug) {
      this.$router.push(`/projects/${slug}`)
    }
  }
}
</script>

